class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.map = new Map(); // Map 保持插入顺序：队首最旧，队尾最新
  }

  get(key) {
    if (!this.map.has(key)) return -1;
    const value = this.map.get(key);
    this.map.delete(key);
    this.map.set(key, value); // 重新插入，刷新为最近使用
    return value;
  }

  put(key, value) {
    if (this.map.has(key)) {
      this.map.delete(key);           // 已存在：先删，稍后刷新顺序
    } else if (this.map.size >= this.capacity) {
      const oldestKey = this.map.keys().next().value; // 最久未使用
      this.map.delete(oldestKey);
    }
    this.map.set(key, value);
  }
}

// 测试
const lru = new LRUCache(2);
lru.put('a', 1);
lru.put('b', 2);
console.log(lru.get('a'));   // 1，a 被刷新为最近使用，b 变成最旧
lru.put('c', 3);             // 容量 2 已满，淘汰 b
console.log(lru.get('b'));   // -1，b 已被淘汰
console.log(lru.get('a'));   // 1
console.log(lru.get('c'));   // 3
lru.put('d', 4);             // 淘汰当前最旧的 a
console.log(lru.get('a'));   // -1
console.log([...lru.map.keys()]); // [ 'c', 'd' ]
